    inp=s["messages"][1]["content"]
    if isinstance(inp,list): inp="".join(b.get("text","") for b in inp)
    return inp

# ---- ranking variants -------------------------------------------------
def grams_char(t):
    t="".join(t.split()); return collections.Counter(t[i:i+2] for i in range(len(t)-1))
def grams_word(t):
    w=t.lower().split(); c=collections.Counter(w); c.update(" ".join(p) for p in zip(w,w[1:])); return c

def idf_doc(inputs, reader):
    carried=collections.Counter()
    for t in inputs: carried.update(set(reader(t)))
    n=len(inputs)
    return {g: math.log((n+1)/(c+1)) for g,c in carried.items()}, math.log(n+1)

def idf_answer(examples, reader, answer_of):
    """Weight by how many *distinct answers* carry the n-gram (supervised)."""
    carried=collections.Counter(); total=set()
    for e in examples:
        a=answer_of(e)
        for g in set(reader(e.get("raw_question", e["input"]))):
            carried[g]+=1; total.add((g,a))
